set -e; : "${PREFIX:?请在 Termux 中运行}"; pkg install -y openssh termux-services; mkdir -p ~/.ssh && chmod 700 ~/.ssh; grep -Fqx {{public_key}} ~/.ssh/authorized_keys 2>/dev/null || echo {{public_key}} >> ~/.ssh/authorized_keys; chmod 600 ~/.ssh/authorized_keys; ssh-keygen -A; {{start_script}}; mkdir -p ~/.termux/boot; printf '#!/data/data/com.termux/files/usr/bin/sh\n. "$PREFIX/etc/profile.d/start-services.sh"\n' > ~/.termux/boot/start-sshd; chmod +x ~/.termux/boot/start-sshd; echo "OK $(whoami)"
